INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(1, 1, '2026-05-01 12:30:02', '2026-05-01 12:30:02', '<!-- wp:paragraph -->\n<p>Welcome to WordPress. This is your first post. Edit or delete it, then start writing!</p>\n<!-- /wp:paragraph -->', 'Hello world!', '', 'trash', 'open', 'open', '', 'hello-world__trashed', '', '', '2026-05-02 22:20:35', '2026-05-02 22:20:35', '', 0, 'http://localhost/decor-shop/?p=1', 0, 'post', '', 1),
(2, 1, '2026-05-01 12:30:02', '2026-05-01 12:30:02', '<!-- wp:paragraph -->\n<p>This is an example page. It\'s different from a blog post because it will stay in one place and will show up in your site navigation (in most themes). Most people start with an About page that introduces them to potential site visitors. It might say something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>Hi there! I\'m a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like pi&#241;a coladas. (And gettin\' caught in the rain.)</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>...or something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>As a new WordPress user, you should go to <a href=\"http://localhost/decor-shop/wp-admin/\">your dashboard</a> to delete this page and create new pages for your content. Have fun!</p>\n<!-- /wp:paragraph -->', 'Sample Page', '', 'trash', 'closed', 'open', '', 'sample-page__trashed', '', '', '2026-05-01 15:00:27', '2026-05-01 15:00:27', '', 0, 'http://localhost/decor-shop/?page_id=2', 0, 'page', '', 0),
(3, 1, '2026-05-01 12:30:02', '2026-05-01 12:30:02', '<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">1. Συλλογή Δεδομένων</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Συλλέγουμε τα παρακάτω προσωπικά δεδομένα κατά την υποβολή παραγγελίας ή επικοινωνίας μαζί μας: ονοματεπώνυμο, διεύθυνση, email, τηλέφωνο.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">2. Χρήση Δεδομένων</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Τα δεδομένα σας χρησιμοποιούνται αποκλειστικά για την επεξεργασία παραγγελιών, την αποστολή προϊόντων και την επικοινωνία μαζί σας. Δεν διαβιβάζουμε τα δεδομένα σας σε τρίτους εκτός από τις εταιρείες courier για τις ανάγκες αποστολής.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">3. Cookies</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Ο ιστότοπός μας χρησιμοποιεί cookies για τη βελτίωση της εμπειρίας πλοήγησης. Μπορείτε να απενεργοποιήσετε τα cookies από τις ρυθμίσεις του browser σας.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">4. Δικαιώματα Χρηστών</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Σύμφωνα με τον GDPR έχετε δικαίωμα πρόσβασης, διόρθωσης και διαγραφής των προσωπικών σας δεδομένων. Για οποιοδήποτε αίτημα επικοινωνήστε στο <a href=\"mailto:info@aegeandecor.gr\">info@aegeandecor.gr</a>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">5. Ασφάλεια Δεδομένων</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Λαμβάνουμε όλα τα απαραίτητα τεχνικά μέτρα για την προστασία των προσωπικών σας δεδομένων από μη εξουσιοδοτημένη πρόσβαση.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">6. Επικοινωνία</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Για οποιοδήποτε θέμα σχετικό με την πολιτική απορρήτου επικοινωνήστε στο: <a href=\"mailto:info@aegeandecor.gr\">info@aegeandecor.gr</a></p>\n<!-- /wp:paragraph -->', 'Πολιτική Απορρήτου', '', 'publish', 'closed', 'open', '', 'privacy-policy', '', '', '2026-05-02 23:54:30', '2026-05-02 23:54:30', '', 0, 'http://localhost/decor-shop/?page_id=3', 0, 'page', '', 0),
