(264, 1, '2026-05-03 10:28:00', '2026-05-03 10:28:00', '<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Κατηγορίες</h2>\n<!-- /wp:heading -->\n\n<!-- wp:shortcode -->\n[smartslider3 slider=\"2\"]\n<!-- /wp:shortcode -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Δημοφιλέστερα</h2>\n<!-- /wp:heading -->\n\n<!-- wp:shortcode -->\n[best_selling_products limit=\"4\"]\n<!-- /wp:shortcode -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Καλύτερες Αξιολογήσεις</h2>\n<!-- /wp:heading -->\n\n<!-- wp:shortcode -->\n[top_rated_products limit=\"3\"]\n<!-- /wp:shortcode -->\n\n<!-- wp:html -->\n<style>\n@import url(\'https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,600;1,400&family=Jost:wght@300;400;500&display=swap\');\n\n.banners-wrap {\n  display: flex;\n  flex-direction: column;\n  gap: 2rem;\n  align-items: center;\n  padding: 1.5rem 0;\n}\n\n/* BANNER 1 - Leaderboard 728x90 */\n.banner1 {\n  width: 728px; height: 90px;\n  background: #1a2744;\n  display: flex; align-items: center;\n  justify-content: space-between;\n  padding: 0 28px;\n  position: relative; overflow: hidden;\n  font-family: \'Jost\', sans-serif;\n  flex-shrink: 0;\n}\n.banner1::before {\n  content: \'\';\n  position: absolute; left: 0; top: 0;\n  width: 180px; height: 100%;\n  background: linear-gradient(90deg, #c4a882 0%, transparent 100%);\n  opacity: 0.15;\n}\n.b1-left { display: flex; align-items: center; gap: 16px; }\n.b1-brand { font-family: \'Cormorant Garamond\', serif; font-size: 18px; color: #c4a882; letter-spacing: .04em; }\n.b1-divider { width: 1px; height: 36px; background: rgba(196,168,130,0.3); }\n.b1-text h3 { font-size: 15px; font-weight: 500; color: #fff; letter-spacing: .02em; margin: 0 0 2px; }\n.b1-text p { font-size: 11px; color: rgba(255,255,255,0.55); margin: 0; letter-spacing: .03em; }\n.b1-right { display: flex; align-items: center; gap: 20px; }\n.b1-price { text-align: right; }\n.b1-price span { display: block; font-size: 11px; color: rgba(255,255,255,0.45); }\n.b1-price strong { font-size: 22px; font-weight: 300; color: #c4a882; }\n.b1-btn {\n  background: #c4a882; color: #1a2744;\n  font-family: \'Jost\', sans-serif;\n  font-size: 11px; font-weight: 500;\n  letter-spacing: .1em; text-transform: uppercase;\n  padding: 10px 20px; border: none; cursor: pointer;\n  white-space: nowrap; text-decoration: none;\n  display: inline-block;\n}\n\n/* BANNER 2 - Medium Rectangle 300x250 */\n.banner2 {\n  width: 300px; height: 250px;\n  background: #f5f0e8;\n  position: relative; overflow: hidden;\n  font-family: \'Jost\', sans-serif;\n  display: flex; flex-direction: column;\n  align-items: center; justify-content: center;\n  flex-shrink: 0;\n}\n.banner2::before {\n  content: \'\';\n  position: absolute; top: -40px; right: -40px;\n  width: 160px; height: 160px;\n  border-radius: 50%;\n  background: #d4c4a0;\n  opacity: 0.25;\n}\n.banner2::after {\n  content: \'\';\n  position: absolute; bottom: -30px; left: -30px;\n  width: 100px; height: 100px;\n  border-radius: 50%;\n  background: #b8956a;\n  opacity: 0.15;\n}\n.b2-tag {\n  font-size: 10px; letter-spacing: .15em;\n  text-transform: uppercase; color: #b8956a;\n  margin-bottom: 8px; position: relative; z-index: 1;\n}\n.b2-title {\n  font-family: \'Cormorant Garamond\', serif;\n  font-size: 26px; font-weight: 600;\n  color: #2c2416; text-align: center;\n  line-height: 1.2; margin: 0 0 4px;\n  position: relative; z-index: 1;\n}\n.b2-sub {\n  font-size: 11px; color: #8a7a65;\n  letter-spacing: .05em; margin-bottom: 16px;\n  position: relative; z-index: 1;\n}\n.b2-price {\n  font-size: 28px; font-weight: 300;\n  color: #2c2416; margin-bottom: 18px;\n  position: relative; z-index: 1;\n}\n.b2-price span { font-size: 14px; }\n.b2-btn {\n  background: #2c2416; color: #f5f0e8;\n  font-family: \'Jost\', sans-serif;\n  font-size: 10px; font-weight: 500;\n  letter-spacing: .12em; text-transform: uppercase;\n  padding: 10px 28px; border: none; cursor: pointer;\n  position: relative; z-index: 1;\n  text-decoration: none; display: inline-block;\n}\n.b2-brand {\n  position: absolute; bottom: 12px; right: 14px;\n  font-family: \'Cormorant Garamond\', serif;\n  font-size: 11px; color: #b8956a; letter-spacing: .05em;\n  font-style: italic; z-index: 1;\n}\n</style>\n\n<div class=\"banners-wrap\">\n\n  <!-- BANNER 1: Leaderboard 728x90 - Καναπές Santorini -->\n  <div class=\"banner1\">\n    <div class=\"b1-left\">\n      <div class=\"b1-brand\">Aegean Decor</div>\n      <div class=\"b1-divider\"></div>\n      <div class=\"b1-text\">\n        <h3>Καναπές Santorini</h3>\n        <p>Τριθέσιος · Διαθέσιμος σε 3 χρώματα & 2 υφάσματα</p>\n      </div>\n    </div>\n    <div class=\"b1-right\">\n      <div class=\"b1-price\">\n        <span>από</span>\n        <strong>€699</strong>\n      </div>\n      <a href=\"/decor-shop/product/καναπές-santorini-3θέσιος/\" class=\"b1-btn\">Αγόρασε Τώρα →</a>\n    </div>\n  </div>\n\n  <!-- BANNER 2: Medium Rectangle 300x250 - Βάζο Thira -->\n  <div class=\"banner2\">\n    <div class=\"b2-tag\">Νέα Συλλογή 2025</div>\n    <div class=\"b2-title\">Βάζο<br>Thira</div>\n    <div class=\"b2-sub\">Χειροποίητο κεραμικό · Aegean style</div>\n    <div class=\"b2-price\"><span>€</span>45</div>\n    <a href=\"/decor-shop/product/βάζο-κεραμικό-thira/\" class=\"b2-btn\">Δες το Προϊόν →</a>\n    <div class=\"b2-brand\">Aegean Decor</div>\n  </div>\n\n</div>\n<!-- /wp:html -->', 'Αρχική Σελίδα', '', 'inherit', 'closed', 'closed', '', '45-revision-v1', '', '', '2026-05-03 10:28:00', '2026-05-03 10:28:00', '', 45, 'http://localhost/decor-shop/?p=264', 0, 'revision', '', 0);
